using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();

app.MapMcp();
app.MapGet("/health", () => "ok");

app.Run();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/features/{featureName}",
        Name = "Feature Flag",
        MimeType = "application/json"),
     Description("Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(
        [Description("Name of the feature flag to look up")] string featureName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["Caching"] = true,
            ["Logging"] = true,
            ["DarkMode"] = false,
            ["BetaFeatures"] = false
        };

        var result = new
        {
            Feature = featureName,
            Enabled = flags.TryGetValue(featureName, out var enabled) && enabled,
            Found = flags.ContainsKey(featureName)
        };

        return JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Lists all available feature flag names.")]
    public static string ListFeatureFlags()
    {
        var flags = new[] { "Caching", "Logging", "DarkMode", "BetaFeatures" };
        return JsonSerializer.Serialize(flags);
    }

    [McpServerTool, Description("Checks whether a specific feature flag is enabled.")]
    public static string CheckFeatureFlag(
        [Description("The name of the feature flag to check")] string flagName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["Caching"] = true,
            ["Logging"] = true,
            ["DarkMode"] = false,
            ["BetaFeatures"] = false
        };

        bool enabled = flags.TryGetValue(flagName, out var val) && val;
        return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}.";
    }
}

